int netlink_dump(struct sock *sk) {
    struct sk_buff *skb;
    int err = 0;

    mutex_lock(&sk->sk_lock);
    if (sk->sk_callback_running) {
        mutex_unlock(&sk->sk_lock);
        return -EBUSY;
    }

    if (sk->sk_rcvbuf_used >= sk->sk_rcvbuf) {
        mutex_unlock(&sk->sk_lock);
        return -ENOBUFS;
    }

    skb = alloc_skb(sk->sk_rcvbuf / 2, GFP_KERNEL);
    if (!skb) {
        mutex_unlock(&sk->sk_lock);
        return -ENOMEM;
    }

    err = sk->sk_dump(skb, sk);
    if (err < 0) {
        kfree_skb(skb);
        mutex_unlock(&sk->sk_lock);
        return err;
    }

    if (sk->sk_filter) {
        skb = sk_filter(sk, skb);
        if (!skb) {
            mutex_unlock(&sk->sk_lock);
            return -EINVAL;
        }
    }

    sk->sk_rcvbuf_used += skb->len;
    netlink_unicast(sk, skb, sk->sk_peer_pid, 0);

    mutex_unlock(&sk->sk_lock);
    return 0;
}

int netlink_dump(struct sock *sk) {
    struct sk_buff *skb;
    int err = 0;

    mutex_lock(&sk->sk_lock);
    if (sk->sk_callback_running) {
        mutex_unlock(&sk->sk_lock);
        return -EBUSY;
    }

    if (sk->sk_rcvbuf * 3 / 4 > sk->sk_rmem_alloc)
        skb = alloc_skb(sk->sk_rcvbuf, GFP_KERNEL);
    else
        skb = alloc_skb(sk->sk_rcvbuf / 2, GFP_KERNEL);

    if (!skb) {
        mutex_unlock(&sk->sk_lock);
        return -ENOMEM;
    }

    sk->sk_callback_running = 1;
    mutex_unlock(&sk->sk_lock);

    err = sk->sk_prot->dump(skb, sk);
    if (err < 0) {
        kfree_skb(skb);
        return err;
    }

    if (skb->len > 0) {
        if (sk_filter(sk, skb))
            kfree_skb(skb);
        else
            sock_queue_rcv_skb(sk, skb);
    } else {
        kfree_skb(skb);
    }

    mutex_lock(&sk->sk_lock);
    sk->sk_callback_running = 0;
    mutex_unlock(&sk->sk_lock);

    return 0;
}

int nl_dump_messages(struct sock *sk) {
