int nlmsg_dumphandler(struct sock *sk)
{
    struct sk_buff *skb;
    int err = 0;

    mutex_lock(&sk->sk_mutex);
    if (sk->sk_callback_running) {
        mutex_unlock(&sk->sk_mutex);
        return -EBUSY;
    }

    if (sk_rmem_limit && (atomic_read(&sk->sk_rmem_alloc) >= sk_rmem_limit)) {
        mutex_unlock(&sk->sk_mutex);
        return -ENOBUFS;
    }

    skb = alloc_skb(NLMSG_GOODSIZE, GFP_KERNEL);
    if (!skb) {
        mutex_unlock(&sk->sk_mutex);
        return -ENOMEM;
    }

    sk->sk_callback_running = 1;
    mutex_unlock(&sk->sk_mutex);

    err = sk->sk_prot->dump(skb, sk);
    if (err < 0) {
        kfree_skb(skb);
        return err;
    }

    if (sk->sk_filter) {
        skb_set_owner_r(skb, sk);
        sock_queue_rcv_skb(sk, skb);
    } else {
        kfree_skb(skb);
    }

    mutex_lock(&sk->sk_mutex);
    sk->sk_callback_running = 0;
    mutex_unlock(&sk->sk_mutex);

    return 0;
}
